const fields = $json.body.data.fields;

const getField = (label) => {
  const f = fields.find(f => (f.label || '').trim().toLowerCase() === label.toLowerCase());
  return f ? f.value : null;
};

return [{
  json: {
    namn: getField('Namn'),
    epost: getField('E-post'),
    telefon: getField('Telefon'),
    meddelande: getField('Meddelande'),
    objekt: getField('objekt')
  }
}];

const lead = $('Extract lead fields').item.json;

let category;
try {
  category = JSON.parse($json.output[0].content[0].text);
} catch (e) {
  category = { temperatur: 'kallt', prioritet: 'låg', motivering: 'Kunde inte tolka AI-svaret.' };
}

return [{
  json: {
    namn: lead.namn,
    'e-post': lead.epost,
    telefon: lead.telefon,
    objekt: lead.objekt,
    temperatur: category.temperatur,
    prioritet: category.prioritet,
    motivering: category.motivering
  }
}];
